import{_ as a,a0 as p,w as l,s as n,I as o,x as t,a1 as s,A as i,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 vi 中创建快捷键 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 vi 中创建快捷键 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 vi 中创建快捷键 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 vi 中创建快捷键 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180531 How to create shortcuts in vi","title":"如何在 vi 中创建快捷键","tag":"201810","desc":""},"relativePath":"201810/20180531 How to create shortcuts in vi.md","filePath":"[post].md"}'),r={name:"201810/20180531 How to create shortcuts in vi.md"};function h(g,e,u,v,b,m){const d=p("Link");return l(),n("div",null,[e[21]||(e[21]=o("h1",{id:"如何在-vi-中创建快捷键",tabindex:"-1"},[t("如何在 vi 中创建快捷键 "),o("a",{class:"header-anchor",href:"#如何在-vi-中创建快捷键","aria-label":"Permalink to “如何在 vi 中创建快捷键”"},"​")],-1)),e[22]||(e[22]=o("blockquote",null,[o("p",null,"那些常见编辑任务的快捷键可以使 Vi 编辑器更容易使用，更有效率。")],-1)),e[23]||(e[23]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/documentation-type-keys-yearbook.png?itok=Q-ELM2rn",alt:""})],-1)),o("p",null,[e[1]||(e[1]=t("学习使用 ",-1)),s(d,{href:"http://ex-vi.sourceforge.net/"},{default:i(()=>[...e[0]||(e[0]=[t("vi 文本编辑器",-1)])]),_:1}),e[2]||(e[2]=t(" 确实得花点功夫，不过 vi 的老手们都知道，经过一小会儿的锻炼，就可以将基本的 vi 操作融汇贯通。我们都知道“肌肉记忆”，那么学习 vi 的过程可以称之为“手指记忆”。",-1))]),e[24]||(e[24]=o("p",null,"当你抓住了基础的操作窍门之后，你就可以定制化地配置 vi 的快捷键，从而让其处理的功能更为强大、流畅。我希望下面描述的技术可以加速您的协作、编程和数据操作。",-1)),o("p",null,[e[4]||(e[4]=t("在开始之前，我想先感谢下 Chris Hermansen（是他雇佣我写了这篇文章）仔细地检查了我的另一篇关于使用 vi 增强版本 ",-1)),s(d,{href:"https://www.vim.org/"},{default:i(()=>[...e[3]||(e[3]=[t("Vim",-1)])]),_:1}),e[5]||(e[5]=t(" 的文章。当然还有他那些我未采纳的建议。",-1))]),e[25]||(e[25]=c(`<p>首先，我们来说明下面几个惯例设定。我会使用符号 <code>&lt;RET&gt;</code> 来代表按下回车，<code>&lt;SP&gt;</code> 代表按下空格键，<code>CTRL-x</code> 表示一起按下 <code>Control</code> 键和 <code>x</code> 键（<code>x</code> 可以是需要的某个键）。</p><p>使用 <code>map</code> 命令来进行按键的映射。第一个例子是 <code>write</code> 命令，通常你之前保存使用这样的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w&lt;RET&gt;</span></span></code></pre></div><p>虽然这里只有三个键，不过考虑到我用这个命令实在是太频繁了，我更想“一键”搞定它。在这里我选择逗号键，它不是标准的 vi 命令集的一部分。这样设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map , :wCTRL-v&lt;RET&gt;</span></span></code></pre></div><p>这里的 <code>CTRL-v</code> 事实上是对 <code>&lt;RET&gt;</code> 做了转义的操作，如果不加这个的话，默认 <code>&lt;RET&gt;</code> 会作为这条映射指令的结束信号，而非映射中的一个操作。 <code>CTRL-v</code> 后面所跟的操作会翻译为用户的实际操作，而非该按键平常的操作。</p><p>在上面的映射中，右边的部分会在屏幕中显示为 <code>:w^M</code>，其中 <code>^</code> 字符就是指代 <code>control</code>，完整的意思就是 <code>CTRL-m</code>，表示就是系统中一行的结尾。</p><p>目前来说，就很不错了。如果我编辑、创建了十二次文件，这个键位映射就可以省掉了 2*12 次按键。不过这里没有计算你建立这个键位映射所花费的 11 次按键（计算 <code>CTRL-v</code> 和 <code>:</code> 均为一次按键）。虽然这样已经省了很多次，但是每次打开 vi 都要重新建立这个映射也会觉得非常麻烦。</p><p>幸运的是，这里可以将这些键位映射放到 vi 的启动配置文件中，让其在每次启动的时候自动读取：文件为 <code>.exrc</code>，对于 vim 是 <code>.vimrc</code>。只需要将这些文件放在你的用户根目录中即可，并在文件中每行写入一个键位映射，之后就会在每次启动 vi 生效直到你删除对应的配置。</p><p>在继续说明 <code>map</code> 其他用法以及其他的缩写机制之前，这里在列举几个我常用提高文本处理效率的 map 设置：</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>显示为</th></tr></thead><tbody><tr><td><code>:map X :xCTRL-v&lt;RET&gt;</code></td><td><code>:x^M</code></td></tr><tr><td><code>:map X ,:qCTRL-v&lt;RET&gt;</code></td><td><code>,:q^M</code></td></tr></tbody></table></div><p>上面的 <code>map</code> 指令的意思是写入并关闭当前的编辑文件。其中 <code>:x</code> 是 vi 原本的命令，而下面的版本说明之前的 <code>map</code> 配置可以继续用作第二个 <code>map</code> 键位映射。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>显示为</th></tr></thead><tbody><tr><td><code>:map v :e&lt;SP&gt;</code></td><td><code>:e</code></td></tr></tbody></table></div><p>上面的指令意思是在 vi 编辑器内部切换文件，使用这个时候，只需要按 <code>v</code> 并跟着输入文件名，之后按 <code>&lt;RET&gt;</code> 键。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>显示为</th></tr></thead><tbody><tr><td><code>:map CTRL-vCTRL-e :e&lt;SP&gt;#CTRL-v&lt;RET&gt;</code></td><td><code>:e #^M</code></td></tr></tbody></table></div><p><code>#</code> 在这里是 vi 中标准的符号，意思是最后使用的文件名。所以切换当前与上一个文件的方法就使用上面的映射。</p><div class="table-wrap"><table><thead><tr><th>映射</th><th>显示为</th></tr></thead><tbody><tr><td><code>map CTRL-vCTRL-r :!spell %&gt;err &amp;CTRL-v&lt;RET&gt;</code></td><td><code>:!spell %&gt;err&amp;^M</code></td></tr></tbody></table></div><p>（注意：在两个例子中出现的第一个 <code>CRTL-v</code> 在某些 vi 的版本中是不需要的）其中，<code>:!</code> 用来运行一个外部的（非 vi 内部的）命令。在这个拼写检查的例子中，<code>%</code> 是 vi 中的符号用来指代目前的文件， <code>&gt;</code> 用来重定向拼写检查中的输出到 <code>err</code> 文件中，之后跟上 <code>&amp;</code> 说明该命令是一个后台运行的任务，这样可以保证在拼写检查的同时还可以进行编辑文件的工作。这里我可以键入 <code>verr&lt;RET&gt;</code>（使用我之前定义的快捷键 <code>v</code> 跟上 <code>err</code>），进入 <code>spell</code> 输出结果的文件，之后再输入 <code>CTRL-e</code> 来回到刚才编辑的文件中。这样我就可以在拼写检查之后，使用 <code>CTRL-r</code> 来查看检查的错误，再通过 <code>CTRL-e</code> 返回刚才编辑的文件。</p><p>还用很多字符串输入的缩写，也使用了各种 <code>map</code> 命令，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map! CTRL-o \\fI</span></span>
<span class="line"><span>:map! CTRL-k \\fP</span></span></code></pre></div><p>这个映射允许你使用 <code>CTRL-o</code> 作为 <code>groff</code> 命令的缩写，从而让让接下来书写的单词有斜体的效果，并使用 <code>CTRL-k</code> 进行恢复。</p><p>还有两个类似的映射：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map! rh rhinoceros</span></span>
<span class="line"><span>:map! hi hippopotamus</span></span></code></pre></div><p>上面的也可以使用 <code>ab</code> 命令来替换，就像下面这样（如果想这么用的话，需要首先按顺序运行： 1、 <code>unmap! rh</code>，2、<code>umap! hi</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab rh rhinoceros</span></span>
<span class="line"><span>:ab hi hippopotamus</span></span></code></pre></div><p>在上面 <code>map!</code> 的命令中，缩写会马上的展开成原有的单词，而在 <code>ab</code> 命令中，单词展开的操作会在输入了空格和标点之后才展开（不过在 Vim 和我的 vi 中，展开的形式与 <code>map!</code> 类似）。</p><p>想要取消刚才设定的按键映射，可以对应的输入 <code>:unmap</code>、 <code>unmap!</code> 或 <code>:unab</code>。</p><p>在我使用的 vi 版本中，比较好用的候选映射按键包括 <code>g</code>、<code>K</code>、<code>q</code>、 <code>v</code>、 <code>V</code>、 <code>Z</code>，控制字符包括：<code>CTRL-a</code>、<code>CTRL-c</code>、 <code>CTRL-k</code>、<code>CTRL-n</code>、<code>CTRL-p</code>、<code>CTRL-x</code>；还有一些其他的字符如 <code>#</code>、 <code>*</code>，当然你也可以使用那些已经在 vi 中有过定义但不经常使用的字符，比如本文选择 <code>X</code> 和 <code>I</code>，其中 <code>X</code> 表示删除左边的字符，并立刻左移当前字符。</p><p>最后，下面的命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:map&lt;RET&gt;</span></span>
<span class="line"><span>:map!&lt;RET&gt;</span></span>
<span class="line"><span>:ab</span></span></code></pre></div><p>将会显示，目前所有的缩写和键位映射。</p><p>希望上面的技巧能够更好地更高效地帮助你使用 vi。</p><hr>`,33)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),s(d,{href:"https://opensource.com/article/18/5/shortcuts-vi-text-editor"},{default:i(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/18/5/shortcuts-vi-text-editor",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：",-1)),s(d,{href:"https://opensource.com/users/dannyman"},{default:i(()=>[...e[8]||(e[8]=[t("Dan Sonnenschein",-1)])]),_:1}),e[13]||(e[13]=t(" \u2028选题：",-1)),s(d,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" \u2028译者：",-1)),s(d,{href:"https://github.com/sd886393"},{default:i(()=>[...e[10]||(e[10]=[t("sd886393",-1)])]),_:1}),e[15]||(e[15]=t(" \u2028校对：",-1)),s(d,{href:"https://github.com/wxy"},{default:i(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=t("本文由 ",-1)),s(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创编译，",-1)),s(d,{href:"https://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const f=a(r,[["render",h]]);export{C as __pageData,f as default};
